نقش سازمانی: مدیر تعمیرات و قابلیت اطمینان (maintenance_manager)

درخواست کاربر:
گزارش عملکرد تعمیرات این ماه را بده. (مدیر تعمیرات — معدن سنگ‌آهن گل‌گهر)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "equipment_downtime",
      "description": "توقف تجهیزات به تفکیک نوع و علت",
      "dimensions": [
        "equipment",
        "reason",
        "period"
      ],
      "measures": [
        "hours",
        "cost"
      ]
    },
    {
      "dataset": "maintenance_work_orders",
      "description": "دستورات کار تعمیراتی",
      "dimensions": [
        "equipment",
        "type",
        "period"
      ],
      "measures": [
        "planned",
        "completed",
        "overdue"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "availability",
      "description": "نرخ دسترسی تجهیز",
      "formula": "زمان کار / (زمان کار + زمان توقف)",
      "unit": "درصد",
      "dimensions": [
        "equipment"
      ]
    },
    {
      "metric": "mtbf",
      "description": "میانگین زمان بین خرابی‌ها",
      "formula": "کل زمان کار / تعداد خرابی‌ها",
      "unit": "ساعت",
      "dimensions": [
        "equipment"
      ]
    },
    {
      "metric": "mttr",
      "description": "میانگین زمان تعمیر",
      "formula": "کل زمان تعمیر / تعداد تعمیرات",
      "unit": "ساعت",
      "dimensions": [
        "equipment"
      ]
    }
  ],
  "business_context": [
    "ناوگان تجهیزات معدنی شامل شاول، دامپر، سنگ‌شکن و آسیاب",
    "تعمیرات پیشگیرانه و اضطراری با بودجهٔ سالانه",
    "قطعات حیاتی با زمان تحویل طولانی (۳ تا ۶ ماه)"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "availability",
      "mtbf",
      "mttr"
    ],
    "period": "this_month"
  }
}

TOOL_OBSERVATION:
{
  "availability_pct": 88,
  "mtbf_hours": 234,
  "mttr_hours": 4
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "maintenance_work_orders",
    "filters": {
      "period": "this_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "planned": 43,
  "completed": 37,
  "overdue": 6
}

